<?php include 'db.php'; require_role('Patient'); $pid=current_entity_id($conn,'Patient'); $page_title='Reports'; include 'header.php'; ?>
<h2>My Radiology Reports</h2><table><tr><th>Report ID</th><th>Date</th><th>Test</th><th>Findings</th><th>Diagnosis</th></tr><?php $q=$conn->query("SELECT RR.*, RT.Test_Name FROM RADIOLOGY_REPORT RR JOIN APPOINTMENT A ON RR.Appointment_ID=A.Appointment_ID JOIN RADIOLOGY_TEST RT ON A.Test_ID=RT.Test_ID WHERE A.Patient_ID=$pid"); while($r=$q->fetch_assoc()): ?><tr><td><?=esc($r['Report_ID'])?></td><td><?=esc($r['Report_Date'])?></td><td><?=esc($r['Test_Name'])?></td><td><?=esc($r['Findings'])?></td><td><?=esc($r['Diagnosis'])?></td></tr><?php endwhile; ?></table><?php include 'footer.php'; ?>